const demo = $('Choose a demo').first().json.demoCase;
const cases = {
  healthy: {expectedIds:['DEMO-A','DEMO-B','DEMO-C'], completedIds:['DEMO-C','DEMO-A','DEMO-B']},
  missing: {expectedIds:['DEMO-A','DEMO-B','DEMO-C'], completedIds:['DEMO-A','DEMO-C']},
  wrong_ids: {expectedIds:['DEMO-A','DEMO-B','DEMO-C'], completedIds:['DEMO-A','DEMO-B','DEMO-Z']},
  duplicates: {expectedIds:['DEMO-A','DEMO-B','DEMO-C'], completedIds:['DEMO-A','DEMO-A','DEMO-B']},
  empty: {expectedIds:['DEMO-A','DEMO-B','DEMO-C'], completedIds:[]}
};
if (!Object.hasOwn(cases, demo)) throw new Error('Choose healthy, missing, wrong_ids, duplicates, or empty.');
return [{json:{...cases[demo], allowEmptyExpected:false}}];

// This node expects ONE envelope, including when completedIds is empty.
const inputs = $input.all();
if (inputs.length !== 1) throw new Error('Provide one envelope with expectedIds, completedIds and allowEmptyExpected.');
const data = inputs[0].json;
if (typeof data.allowEmptyExpected !== 'boolean') throw new Error('Set allowEmptyExpected explicitly to true or false.');
for (const field of ['expectedIds', 'completedIds']) {
  if (!Array.isArray(data[field])) throw new Error(`${field} must be an array.`);
  if (data[field].length > 10000) throw new Error(`${field} exceeds this template limit of 10000 IDs.`);
  if (data[field].some(id => typeof id !== 'string' || id.trim().length === 0))
    throw new Error(`${field} must contain nonblank string IDs. Map numeric IDs explicitly before this check.`);
}
function inspect(ids) {
  const unique = new Set();
  const repeated = new Set();
  for (const id of ids) {
    if (unique.has(id)) repeated.add(id);
    unique.add(id);
  }
  return {unique, repeated: [...repeated]};
}
const expected = inspect(data.expectedIds);
const completed = inspect(data.completedIds);
const missingIds = [...expected.unique].filter(id => !completed.unique.has(id));
const unexpectedIds = [...completed.unique].filter(id => !expected.unique.has(id));
const emptyExpectedRejected = expected.unique.size === 0 && !data.allowEmptyExpected;
const matched = !emptyExpectedRejected && missingIds.length === 0 && unexpectedIds.length === 0
  && expected.repeated.length === 0 && completed.repeated.length === 0;
return [{json:{
  matched,
  expectedCount: data.expectedIds.length,
  completedCount: data.completedIds.length,
  missingIds, unexpectedIds,
  duplicateExpectedIds: expected.repeated,
  duplicateCompletedIds: completed.repeated,
  emptyExpectedRejected,
  note: 'Exact string IDs are compared without trimming or case folding; order does not matter. This checks identity coverage, not business correctness or exactly-once execution.'
}}];
